-- Parenthesized joins keep their member tables addressable unless aliased,
-- run RIGHT and FULL joins after a comma as PostgreSQL's join tree, and a
-- join condition sees only the tables its join combines.
CREATE TABLE a119(id int, x int); CREATE TABLE b119(id int, y int); CREATE TABLE c119(id int, z int);
INSERT INTO a119 VALUES (1, 10), (2, 20), (3, 30);
INSERT INTO b119 VALUES (1, 100), (2, 200), (4, 400);
INSERT INTO c119 VALUES (1, 1000), (4, 4000), (5, 5000);
SELECT * FROM (a119 JOIN b119 ON a119.id = b119.id) JOIN c119 ON c119.id = b119.id;
SELECT * FROM a119 LEFT JOIN (b119 JOIN c119 ON b119.id = c119.id) ON a119.id = b119.id ORDER BY 1;
SELECT a119.id, b119.y, c119.z FROM a119 FULL JOIN (b119 LEFT JOIN c119 USING (id)) ON a119.id = b119.id ORDER BY 1, 2, 3;
SELECT * FROM a119 FULL JOIN (b119 LEFT JOIN c119 USING (id)) ON a119.id = b119.id ORDER BY 1, 2, 3;
SELECT j.* FROM (a119 JOIN b119 USING (id)) AS j;
SELECT * FROM (a119 JOIN b119 USING (id)) AS j(p, q, r);
SELECT * FROM (a119 JOIN b119 USING (id)) AS j(p, q, r, s);
SELECT a119.x FROM (a119 JOIN b119 USING (id)) AS j;
SELECT j.id FROM (a119 JOIN b119 ON a119.id = b119.id) AS j;
SELECT * FROM ((a119 JOIN b119 USING (id))) ORDER BY 1;
SELECT count(*) FROM ((a119 JOIN b119 ON true) JOIN (c119 CROSS JOIN b119 AS b2) ON true);
SELECT b119, c119.* FROM a119 LEFT JOIN (b119 JOIN c119 USING (id)) ON a119.id = b119.id ORDER BY a119.id;
SELECT count(b119), count(c119.*), count(*) FROM a119 LEFT JOIN (b119 LEFT JOIN c119 ON b119.id = c119.id) ON a119.id = b119.id;
SELECT * FROM (a119 JOIN b119 USING (id) AS u) JOIN c119 ON u.id = c119.id;
SELECT * FROM a119 JOIN (b119 JOIN c119 ON true) ON true ORDER BY 3 DESC, 5 DESC, 1 LIMIT 3;
SELECT * FROM (SELECT 1 id, 2 id) s ORDER BY 2;
SELECT * FROM a119 NATURAL JOIN (b119 NATURAL JOIN c119);
SELECT * FROM a119, b119 RIGHT JOIN c119 ON b119.id = c119.id ORDER BY 1, 5;
SELECT * FROM a119, b119 FULL JOIN c119 ON b119.id = c119.id WHERE a119.id = 1 ORDER BY 3, 5;
SELECT * FROM (SELECT 1 a), (SELECT 2 a);
UPDATE a119 SET x = x + 1 FROM (b119 JOIN c119 ON b119.id = c119.id) WHERE a119.id = b119.id RETURNING a119.*, b119.y, c119.z;
DELETE FROM a119 USING b119 RIGHT JOIN c119 ON b119.id = c119.id WHERE a119.id = c119.id RETURNING *;
SELECT * FROM a119 JOIN b119 ON c119.id = 1 JOIN c119 ON true;
SELECT * FROM a119 JOIN b119 ON z = 1 JOIN c119 ON true;
SELECT * FROM a119, b119 JOIN c119 ON x = 1;
SELECT * FROM a119, b119 JOIN c119 ON a119.id = c119.id;
SELECT * FROM a119 JOIN (b119 JOIN c119 ON b119.y = a119.x) ON true;
SELECT * FROM a119 JOIN (b119 JOIN c119 ON y = x) ON true;
UPDATE a119 SET x = 1 FROM b119 JOIN c119 ON c119.id = a119.id;
SELECT * FROM a119 JOIN (b119 JOIN a119 ON true) ON true;
SELECT * FROM ((a119));
SELECT * FROM (a119) t;
SELECT a119.x FROM a119 t;
CREATE VIEW v119 AS SELECT b119.y, c119.z FROM a119 LEFT JOIN (b119 JOIN c119 USING (id)) ON a119.id = b119.id;
SELECT * FROM v119 ORDER BY 1;
DROP VIEW v119;
DROP TABLE a119, b119, c119;
